insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$pitangueiras$q$, $q$https://www.diariomunicipal.com.br/amp/materia/0D750B18 (Decreto 437/2018, Diário Oficial dos Municípios do Paraná, 05/11/2018)$q$, $q$Atos oficiais do município: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: polígono desenhado sobre os eixos das vias-limite do OpenStreetMap (ODbL 1.0, © colaboradores do OSM), aproximado.$q$, 1, $q$Decreto 437/2018 (vigente 60 dias após a publicação). Proibição de circulação e estacionamento de caminhões, articulados, tratores, reboques e implementos no Perímetro Central, modelada como 24 h; a carga e descarga de até 10 t de carga entre 17h e 10h (art. 2º) é exceção textual não modelável (nenhum veículo de mais de 3 eixos ou articulado é coberto por ela, art. 3º).$q$);
